/* Decks de psiquiatria geral: os assuntos que mais caem nas provas do banco e que ainda não tinham
   flashcards (ansiedade, psicoses, humor, dependência química, psicofarmacologia, PIA, forense,
   psicoterapia, saúde mental coletiva...). Base: DSM-5-TR e legislação brasileira.
   Cada deck vai para uma área do seletor da aba Flashcards. */
(function addGeneralFlashcardDecks() {
  const root = window.BANCO_RMAIS_FLASHCARDS || (window.BANCO_RMAIS_FLASHCARDS = { decks: [] });
  if (!Array.isArray(root.decks)) root.decks = [];
  const basis = "Temas mais cobrados nas provas do banco · DSM-5-TR e legislação brasileira";
  /* Subtema de cada deck (o mesmo nome usado nas questões): liga os cartões a "Revisar o conceito"
     e à revisão por subtema sem depender da classificação automática pelo texto. */
  const SUBTHEME_BY_DECK = {
    "pg-ansiedade-toc-trauma": "Ansiedade, TOC e trauma",
    "psicoterapia-teorias-tecnicas": "Psicoterapia",
    "forense-etica-legislacao": "Forense, ética e legislação",
    "dq-drogas-intoxicacoes": "Drogas e intoxicações",
    "dq-alcool": "Álcool e abstinência",
    "psicofarmaco-antidepressivos": "Antidepressivos",
    "pg-esquizofrenia-psicoses": "Esquizofrenia e psicoses",
    "pia-tea-neurodesenvolvimento": "TEA e neurodesenvolvimento",
    "psicofarmaco-antipsicoticos": "Antipsicóticos",
    "pia-tdah-disruptivos": "TDAH e comportamento disruptivo",
    "pg-bipolar-mania": "Transtorno bipolar e mania",
    "pg-psicopatologia": "Psicopatologia e exame mental",
    "pg-personalidade": "Personalidade",
    "pg-saude-mental-coletiva": "Saúde mental coletiva",
    "pg-sono": "Sono",
    "psicofarmaco-estabilizadores": "Estabilizadores do humor",
    "pg-transtornos-alimentares": "Alimentares",
    "psicofarmaco-benzodiazepinicos": "Benzodiazepínicos e sedativos",
    "pg-depressao-suicidio": "Depressão e suicídio",
  };

  function deck(id, title, area, importance, cards) {
    return {
      id,
      title,
      area,
      module: title,
      basis,
      importance,
      priorities: ["high-frequency"],
      cards: cards.map(([front, back, tags, trap], index) => ({
        id: `${id}-${String(index + 1).padStart(3, "0")}`,
        topic: tags[0],
        subtheme: SUBTHEME_BY_DECK[id],
        tags,
        front,
        back,
        ...(trap ? { trap } : {}),
      })),
    };
  }

  const decks = [
    deck("pg-ansiedade-toc-trauma", "Ansiedade, TOC e trauma", "Psiquiatria Geral", 5, [
      ["Quais são os critérios centrais do transtorno de ansiedade generalizada (TAG)?", "Ansiedade e preocupação excessivas, difíceis de controlar, na maioria dos dias por pelo menos 6 meses, com 3 ou mais de 6 sintomas: inquietação, fadiga, dificuldade de concentração, irritabilidade, tensão muscular e sono perturbado.", ["Ansiedade", "TAG"], "Em crianças basta 1 dos 6 sintomas físicos."],
      ["O que é necessário para diagnosticar transtorno de pânico?", "Ataques de pânico inesperados e recorrentes, seguidos por pelo menos 1 mês de preocupação persistente com novos ataques ou suas consequências, ou mudança mal-adaptativa de comportamento (evitação).", ["Ansiedade", "Pânico"], "Ataques apenas esperados (diante de um gatilho fóbico) não bastam."],
      ["Como é definido um ataque de pânico?", "Surto abrupto de medo ou desconforto intenso que atinge o pico em minutos, com 4 ou mais de 13 sintomas (palpitação, sudorese, tremor, falta de ar, sufocação, dor torácica, náusea, tontura, calafrios/ondas de calor, parestesias, desrealização/despersonalização, medo de perder o controle, medo de morrer).", ["Ansiedade", "Pânico"]],
      ["Qual o tratamento de primeira linha para pânico e TAG?", "ISRS ou IRSN (sertralina, escitalopram, paroxetina, venlafaxina) e/ou TCC. Benzodiazepínicos só por curto prazo, como ponte no início do antidepressivo.", ["Ansiedade", "Tratamento"], "No pânico, comece com dose baixa: o paciente é sensível à ativação inicial do ISRS."],
      ["Quais situações compõem a agorafobia no DSM-5?", "Medo ou ansiedade em 2 ou mais de 5 situações: transporte público, espaços abertos, locais fechados, filas ou multidões e estar fora de casa sozinho, por pelo menos 6 meses. É diagnóstico independente do transtorno de pânico.", ["Ansiedade", "Agorafobia"]],
      ["Qual o núcleo do transtorno de ansiedade social e como tratar?", "Medo de avaliação negativa em situações sociais, por 6 meses ou mais (especificador: somente desempenho). Tratamento: TCC e ISRS/IRSN; betabloqueador (propranolol) apenas para ansiedade de desempenho pontual.", ["Ansiedade", "Fobia social"]],
      ["Qual o tratamento de escolha da fobia específica?", "Terapia de exposição (TCC). Medicamentos têm papel limitado.", ["Ansiedade", "Fobia específica"], "No subtipo sangue-injeção-ferimentos há resposta vasovagal bifásica, com bradicardia e desmaio."],
      ["Como o DSM-5 define obsessões e compulsões no TOC?", "Obsessões: pensamentos, impulsos ou imagens intrusivos e indesejados que causam ansiedade. Compulsões: comportamentos ou atos mentais repetitivos feitos para neutralizar a ansiedade. Especificadores: insight bom, pobre ou ausente (crenças delirantes) e relacionado a tique.", ["TOC", "Diagnóstico"], "No DSM-5 o TOC saiu dos transtornos de ansiedade e ganhou capítulo próprio."],
      ["Como se trata o TOC?", "ISRS em doses mais altas e por mais tempo (resposta em 8 a 12 semanas), clomipramina e TCC com exposição e prevenção de resposta. Nos refratários, potencializar com antipsicótico em dose baixa (risperidona, aripiprazol).", ["TOC", "Tratamento"]],
      ["Quais transtornos o DSM-5 agrupa como relacionados ao TOC?", "Transtorno dismórfico corporal, transtorno de acumulação, tricotilomania (arrancar cabelos) e transtorno de escoriação (skin picking).", ["TOC", "Classificação"]],
      ["Quais são os 4 grupos de sintomas do TEPT e a duração mínima?", "Após exposição a morte, ameaça de morte, lesão grave ou violência sexual: intrusão, evitação, alterações negativas na cognição e no humor e alterações na excitação e reatividade. Duração maior que 1 mês.", ["Trauma", "TEPT"], "Com 3 dias a 1 mês de sintomas o diagnóstico é transtorno de estresse agudo."],
      ["Qual o tratamento do TEPT?", "Psicoterapias focadas no trauma (TCC focada no trauma, exposição prolongada, terapia de processamento cognitivo, EMDR) são primeira linha; medicamentos: sertralina, paroxetina ou venlafaxina.", ["Trauma", "TEPT"], "Benzodiazepínicos não são recomendados no TEPT, e o debriefing obrigatório logo após o trauma não previne o quadro."],
      ["Quais os prazos do transtorno de adaptação?", "Sintomas emocionais ou comportamentais em até 3 meses após o estressor, que desaparecem em até 6 meses após o fim do estressor ou de suas consequências.", ["Trauma", "Adaptação"]],
      ["Transtorno de ansiedade de separação pode ser diagnosticado em adultos?", "Sim. Duração mínima de 4 semanas em crianças e adolescentes e, tipicamente, 6 meses ou mais em adultos.", ["Ansiedade", "Separação"]],
    ]),

    deck("psicoterapia-teorias-tecnicas", "Psicoterapia - teorias e técnicas", "Psicoterapia", 5, [
      ["Diferencie transferência e contratransferência.", "Transferência: o paciente desloca para o terapeuta sentimentos e padrões de relações importantes do passado. Contratransferência: reações emocionais do terapeuta ao paciente, usadas como instrumento de compreensão.", ["Psicanálise", "Transferência"]],
      ["Como se classificam os mecanismos de defesa por maturidade?", "Imaturos: projeção, cisão, acting out, fantasia esquizoide, comportamento passivo-agressivo. Neuróticos: repressão, deslocamento, formação reativa, intelectualização, isolamento do afeto. Maduros: sublimação, humor, altruísmo, antecipação, supressão.", ["Psicanálise", "Defesas"], "Repressão é inconsciente (neurótica); supressão é consciente (madura)."],
      ["O que é cisão (splitting) e em qual personalidade é típica?", "Ver pessoas e a si mesmo como totalmente bons ou totalmente maus, sem integração. Típica do transtorno de personalidade borderline, junto com a identificação projetiva.", ["Psicanálise", "Defesas"]],
      ["Quais os modelos topográfico e estrutural de Freud?", "Topográfico: consciente, pré-consciente e inconsciente. Estrutural: id (pulsões), ego (mediação com a realidade, defesas) e superego (consciência moral e ideal do ego).", ["Psicanálise", "Freud"]],
      ["Quais as fases psicossexuais de Freud?", "Oral, anal, fálica (complexo de Édipo), latência e genital.", ["Psicanálise", "Desenvolvimento"]],
      ["Associe autor e conceito: Winnicott, Melanie Klein, Bowlby, Mahler.", "Winnicott: mãe suficientemente boa, holding, objeto transicional. Klein: posições esquizoparanoide e depressiva. Bowlby: teoria do apego. Mahler: separação-individuação.", ["Psicanálise", "Autores"]],
      ["Quais os estágios psicossociais de Erikson?", "Oito estágios ao longo da vida, de confiança x desconfiança (lactente) a integridade x desespero (idoso), passando por identidade x confusão de papéis na adolescência.", ["Desenvolvimento", "Erikson"]],
      ["Qual a tríade cognitiva de Beck na depressão?", "Visão negativa de si mesmo, do mundo e do futuro. A TCC trabalha pensamentos automáticos, crenças intermediárias e crenças centrais, além de distorções cognitivas (catastrofização, pensamento dicotômico, leitura mental, personalização).", ["TCC", "Beck"]],
      ["Para quem é a terapia comportamental dialética (DBT) e quais seus módulos?", "Criada por Linehan para borderline com autolesão e comportamento suicida. Módulos: mindfulness, tolerância ao mal-estar, regulação emocional e efetividade interpessoal.", ["DBT", "Borderline"]],
      ["Reforço negativo é o mesmo que punição?", "Não. Reforço (positivo ou negativo) aumenta a frequência do comportamento; o negativo retira um estímulo aversivo. Punição diminui o comportamento. Condicionamento clássico é de Pavlov; operante, de Skinner.", ["Comportamental", "Condicionamento"], "Confundir reforço negativo com punição é a pegadinha clássica."],
      ["O que é dessensibilização sistemática?", "Técnica de Wolpe: relaxamento associado à exposição gradual a uma hierarquia de estímulos temidos. Inundação (flooding) é a exposição direta e intensa ao estímulo máximo.", ["Comportamental", "Exposição"]],
      ["Quais as áreas-problema da terapia interpessoal (TIP)?", "Terapia breve para depressão (Klerman e Weissman) focada em 4 áreas: luto, disputas interpessoais, transição de papéis e déficits interpessoais.", ["TIP", "Depressão"]],
      ["Quais os estágios de mudança de Prochaska e DiClemente?", "Pré-contemplação, contemplação, preparação, ação e manutenção (com possibilidade de recaída). A entrevista motivacional (Miller e Rollnick) usa empatia, desenvolve discrepância, evita confronto e fortalece a autoeficácia.", ["Entrevista motivacional", "Mudança"]],
      ["O que compõe o enquadre (setting) na psicoterapia psicanalítica?", "Regras estáveis de horário, frequência, honorários e sigilo; neutralidade e abstinência do terapeuta; associação livre do paciente e atenção flutuante do analista.", ["Psicanálise", "Setting"]],
    ]),

    deck("forense-etica-legislacao", "Forense, ética e legislação", "Forense", 5, [
      ["Quais os 3 tipos de internação psiquiátrica da Lei 10.216/2001?", "Voluntária (com consentimento do paciente), involuntária (sem consentimento, a pedido de terceiro) e compulsória (determinada pela Justiça). Todas exigem laudo médico circunstanciado.", ["Legislação", "Internação"]],
      ["Qual o prazo para comunicar uma internação involuntária e a quem?", "Em até 72 horas, ao Ministério Público Estadual, pelo responsável técnico do estabelecimento. O mesmo procedimento vale para a alta.", ["Legislação", "Internação"]],
      ["Quando a internação psiquiátrica é indicada pela Lei 10.216?", "Somente quando os recursos extra-hospitalares se mostrarem insuficientes. É vedada a internação em instituições com características asilares.", ["Legislação", "Reforma psiquiátrica"]],
      ["Qual o critério de inimputabilidade do Código Penal (art. 26)?", "Critério biopsicológico: por doença mental ou desenvolvimento mental incompleto ou retardado, era, ao tempo da ação, inteiramente incapaz de entender o caráter ilícito do fato ou de determinar-se de acordo com esse entendimento.", ["Penal", "Imputabilidade"], "Se a capacidade estava apenas reduzida (semi-imputável), a pena é reduzida de 1 a 2/3 ou substituída por medida de segurança."],
      ["O que é a medida de segurança?", "Internação em hospital de custódia ou tratamento ambulatorial para o inimputável ou semi-imputável. Prazo mínimo de 1 a 3 anos; termina com perícia que ateste a cessação da periculosidade.", ["Penal", "Medida de segurança"]],
      ["Embriaguez exclui a imputabilidade?", "A voluntária ou culposa não exclui (art. 28). Só a embriaguez completa por caso fortuito ou força maior isenta de pena. Emoção e paixão também não excluem a imputabilidade.", ["Penal", "Embriaguez"]],
      ["Quem é absolutamente incapaz no Código Civil após o Estatuto da Pessoa com Deficiência?", "Apenas os menores de 16 anos. Relativamente incapazes: maiores de 16 e menores de 18, ébrios habituais e viciados em tóxicos, quem por causa transitória ou permanente não puder exprimir sua vontade, e os pródigos.", ["Civil", "Capacidade"], "Transtorno mental, por si só, não torna a pessoa absolutamente incapaz."],
      ["O que é a tomada de decisão apoiada?", "Instrumento da Lei 13.146/2015: a pessoa com deficiência escolhe pelo menos 2 pessoas idôneas para apoiá-la em decisões da vida civil. A curatela passou a ser medida extraordinária e restrita a atos patrimoniais e negociais.", ["Civil", "Curatela"]],
      ["Quando o médico pode quebrar o sigilo (Código de Ética Médica, art. 73)?", "Por motivo justo, dever legal ou consentimento por escrito do paciente. O sigilo permanece mesmo que o fato seja público ou o paciente tenha morrido.", ["Ética", "Sigilo"]],
      ["O médico assistente pode ser perito do próprio paciente?", "Não. O Código de Ética Médica veda ser perito do próprio paciente, de familiar ou de pessoa com quem tenha relações capazes de influir no trabalho.", ["Ética", "Perícia"]],
      ["Tentativa de suicídio é de notificação compulsória?", "Sim. Violência autoprovocada é de notificação compulsória; a tentativa de suicídio é de notificação imediata (em até 24 horas) à Secretaria Municipal de Saúde.", ["Legislação", "Notificação"]],
      ["Diferencie simulação, transtorno factício e transtorno conversivo.", "Simulação: produção intencional de sintomas com incentivo externo (não é transtorno mental). Factício: intencional, sem incentivo externo óbvio (busca o papel de doente). Conversivo/sintomas somáticos: não intencional.", ["Perícia", "Simulação"]],
      ["O que avalia o exame de sanidade mental no processo penal?", "Instaurado pelo incidente de insanidade mental (art. 149 do CPP), avalia retrospectivamente o estado mental do acusado ao tempo da ação ou omissão.", ["Penal", "Perícia"]],
      ["Quais as regras para a contenção física de pacientes?", "Só por prescrição médica, registrada em prontuário, com monitorização contínua e pelo menor tempo necessário, como último recurso diante de risco iminente.", ["Ética", "Contenção"]],
    ]),

    deck("dq-drogas-intoxicacoes", "Drogas e intoxicações", "Dependência Química", 5, [
      ["Quais os critérios e a gravidade do transtorno por uso de substância no DSM-5?", "11 critérios em 12 meses (controle prejudicado, prejuízo social, uso arriscado, tolerância e abstinência). Gravidade: leve 2-3, moderada 4-5, grave 6 ou mais.", ["Substâncias", "Diagnóstico"], "Tolerância e abstinência não contam quando o uso é feito sob supervisão médica apropriada."],
      ["Como se apresenta a intoxicação por cocaína e como tratar?", "Quadro simpaticomimético: taquicardia, hipertensão, midríase, hipertermia, agitação, dor torácica por vasoespasmo (risco de IAM). Agitação e hipertensão: benzodiazepínicos.", ["Cocaína", "Intoxicação"], "Evite betabloqueador isolado: deixa o estímulo alfa sem oposição."],
      ["Como é a abstinência de cocaína?", "O 'crash': disforia, hipersonia, fadiga, aumento do apetite e fissura. Não ameaça a vida por si, mas há risco de suicídio na fase disfórica.", ["Cocaína", "Abstinência"]],
      ["Quais os sinais da intoxicação por opioides e o antídoto?", "Miose, depressão respiratória e rebaixamento de consciência. Antídoto: naloxona (IV, IM ou intranasal), de meia-vida curta; pode ser preciso repetir doses com opioides de ação longa.", ["Opioides", "Intoxicação"]],
      ["Quais os sinais da abstinência de opioides?", "Midríase, rinorreia, lacrimejamento, bocejos, piloereção, diarreia, cólicas e mialgia. Muito desconfortável, mas raramente letal. Tratamento: metadona ou buprenorfina; clonidina alivia sintomas autonômicos.", ["Opioides", "Abstinência"]],
      ["Quais as opções de manutenção na dependência de opioides?", "Metadona (agonista mu total), buprenorfina (agonista parcial, pode vir com naloxona) e naltrexona (antagonista, exige abstinência prévia de 7 a 10 dias).", ["Opioides", "Tratamento"], "Iniciar buprenorfina cedo demais pode precipitar abstinência."],
      ["Quais os sinais da intoxicação por cannabis?", "Hiperemia conjuntival, aumento do apetite, boca seca, taquicardia, prejuízo de coordenação e do tempo de reação, ansiedade ou paranoia.", ["Cannabis", "Intoxicação"]],
      ["O que é a síndrome de hiperêmese canabinoide?", "Vômitos cíclicos em usuários crônicos e pesados de cannabis, com alívio característico por banhos quentes. Resolve com a interrupção do uso.", ["Cannabis", "Complicações"]],
      ["Qual a relação entre cannabis e psicose?", "Uso precoce, frequente e de alta potência (alto THC) aumenta o risco de psicose e esquizofrenia. O canabidiol (CBD) não é psicotomimético.", ["Cannabis", "Psicose"]],
      ["Qual o tratamento do tabagismo?", "Abordagem cognitivo-comportamental e farmacoterapia: reposição de nicotina (adesivo associado a formas de ação rápida), bupropiona e vareniclina (agonista parcial alfa-4-beta-2, a mais eficaz em monoterapia). Fagerström avalia a dependência.", ["Tabaco", "Tratamento"]],
      ["Quando a bupropiona é contraindicada?", "Epilepsia ou história de convulsão, bulimia e anorexia, retirada abrupta de álcool ou benzodiazepínicos e uso de IMAO, pelo risco de convulsões.", ["Tabaco", "Bupropiona"]],
      ["Qual o mecanismo e o quadro dos alucinógenos (LSD, psilocibina)?", "Agonistas 5-HT2A: alterações perceptivas, sinestesias, midríase. 'Bad trip': ambiente calmo e benzodiazepínico. Pode haver transtorno persistente da percepção (flashbacks).", ["Alucinógenos", "Intoxicação"]],
      ["Qual o sinal típico da intoxicação por fenciclidina ou cetamina?", "Nistagmo (vertical ou horizontal), dissociação, agressividade e hipertensão. São antagonistas NMDA.", ["Dissociativos", "Intoxicação"]],
      ["Qual o risco agudo grave dos inalantes (solventes)?", "Morte súbita por arritmia ('sudden sniffing death'). O uso crônico causa neurotoxicidade e leucoencefalopatia.", ["Inalantes", "Complicações"]],
      ["Quais as complicações do MDMA (ecstasy)?", "Hipertermia, hiponatremia, síndrome serotoninérgica, bruxismo e taquicardia. As anfetaminas dão quadro simpaticomimético mais longo que a cocaína e psicose paranoide.", ["Estimulantes", "MDMA"]],
    ]),

    deck("dq-alcool", "Álcool e abstinência", "Dependência Química", 5, [
      ["Qual a linha do tempo da abstinência alcoólica?", "Tremor e hiperatividade autonômica em 6 a 24 h; convulsões em 12 a 48 h; alucinose alcoólica em 12 a 48 h, com sensório claro; delirium tremens em 48 a 96 h.", ["Álcool", "Abstinência"]],
      ["Como é o delirium tremens e como tratar?", "Desorientação, alucinações visuais ou táteis, hiperatividade autonômica intensa e febre; mortalidade significativa. Tratamento: benzodiazepínico em doses guiadas por sintomas, suporte clínico e tiamina.", ["Álcool", "Delirium tremens"]],
      ["Como a CIWA-Ar gradua a abstinência?", "Menos de 8: leve; 8 a 15: moderada; mais de 15: grave. Orienta a dose de benzodiazepínico.", ["Álcool", "Escalas"]],
      ["Qual benzodiazepínico usar na abstinência alcoólica?", "Diazepam (meia-vida longa, autotitulação). Em hepatopatia grave ou idosos: lorazepam ou oxazepam, metabolizados por glicuronidação, sem metabólitos ativos.", ["Álcool", "Tratamento"]],
      ["Qual a tríade da encefalopatia de Wernicke e a conduta?", "Confusão mental, oftalmoparesia/nistagmo e ataxia (a tríade completa aparece na minoria). Conduta: tiamina parenteral em dose alta, antes da glicose.", ["Álcool", "Wernicke"], "Korsakoff é a sequela amnéstica com confabulação, em grande parte irreversível."],
      ["Quais os medicamentos para manter a abstinência do álcool?", "Naltrexona (antagonista opioide; evitar com opioides e na insuficiência hepática), acamprosato (seguro no fígado; cuidado na insuficiência renal) e dissulfiram (inibe a aldeído desidrogenase). Topiramato e baclofeno são opções off-label.", ["Álcool", "Tratamento"]],
      ["Quais as exigências para usar dissulfiram?", "Consentimento do paciente, abstinência de pelo menos 12 horas e ausência de cardiopatia grave. Com álcool, causa reação pelo acúmulo de acetaldeído (rubor, náusea, taquicardia, hipotensão).", ["Álcool", "Dissulfiram"]],
      ["O que pergunta o CAGE?", "Cut down (sentiu que deveria diminuir?), Annoyed (críticas o irritam?), Guilty (culpa por beber?), Eye-opener (bebe ao acordar?). 2 ou mais respostas positivas sugerem problema. O AUDIT tem 10 itens (OMS).", ["Álcool", "Rastreio"]],
      ["Quais exames sugerem uso pesado de álcool?", "GGT elevada, macrocitose (VCM aumentado), AST/ALT maior que 2 na hepatopatia alcoólica e transferrina deficiente em carboidrato (CDT).", ["Álcool", "Laboratório"]],
      ["Como diferenciar alucinose alcoólica de delirium tremens?", "Na alucinose há alucinações (sobretudo auditivas) com consciência clara e orientação preservada; no delirium tremens há desorientação e flutuação da consciência.", ["Álcool", "Alucinose"]],
      ["Como tratar a convulsão da abstinência alcoólica?", "Com benzodiazepínico. Fenitoína não é eficaz para convulsão de abstinência.", ["Álcool", "Convulsão"]],
      ["Quais outras complicações neurológicas do álcool caem em prova?", "Degeneração cerebelar (ataxia de marcha), Marchiafava-Bignami (desmielinização do corpo caloso), pelagra (deficiência de niacina: dermatite, diarreia, demência) e neuropatia periférica.", ["Álcool", "Complicações"]],
      ["O que é a intervenção breve (FRAMES)?", "Feedback, Responsabilidade, Aconselhamento (Advice), Menu de opções, Empatia e Autoeficácia (Self-efficacy). Útil na atenção primária para uso de risco.", ["Álcool", "Intervenção breve"]],
    ]),

    deck("psicofarmaco-antidepressivos", "Antidepressivos", "Psicofarmacologia", 5, [
      ["Quais os efeitos adversos comuns dos ISRS?", "Náuseas, disfunção sexual, insônia ou sonolência, ativação inicial, hiponatremia (SIADH, sobretudo em idosos) e maior risco de sangramento com AINE ou anticoagulante.", ["ISRS", "Efeitos adversos"]],
      ["O que diferencia fluoxetina e paroxetina?", "Fluoxetina: meia-vida longa (com norfluoxetina), pouca síndrome de descontinuação, inibe fortemente a CYP2D6 e exige 5 semanas antes de IMAO. Paroxetina: mais anticolinérgica, maior síndrome de descontinuação, ganho de peso, evitada na gestação.", ["ISRS", "Farmacocinética"]],
      ["Qual o cuidado cardíaco com citalopram?", "Prolongamento do QT dependente da dose: máximo de 40 mg/dia, e 20 mg/dia acima de 60 anos. O escitalopram também prolonga o QT, em menor grau.", ["ISRS", "QT"]],
      ["Como é a síndrome de descontinuação dos antidepressivos?", "FINISH: sintomas gripais (Flu-like), Insônia, Náusea, Instabilidade (tontura), alterações Sensoriais (choques) e Hiperexcitação. Pior com meia-vida curta (paroxetina, venlafaxina). Retirar gradualmente.", ["Antidepressivos", "Descontinuação"]],
      ["Quais os sinais da síndrome serotoninérgica e o tratamento?", "Início em horas: alteração mental, instabilidade autonômica (hipertermia, taquicardia, sudorese) e alterações neuromusculares (clônus, hiperreflexia, tremor). Suspender, suporte, benzodiazepínico e ciproeptadina.", ["Antidepressivos", "Síndrome serotoninérgica"], "A síndrome neuroléptica maligna é lenta, com rigidez em cano de chumbo e reflexos diminuídos."],
      ["Quais as particularidades dos IRSN?", "Venlafaxina: hipertensão dependente da dose. Duloxetina: útil em dor neuropática e fibromialgia, evitar em hepatopatia. Desvenlafaxina: metabólito ativo da venlafaxina.", ["IRSN", "Efeitos adversos"]],
      ["Qual o perfil da bupropiona?", "Inibe a recaptação de dopamina e noradrenalina; não causa disfunção sexual nem ganho de peso e ajuda no tabagismo. Reduz o limiar convulsivo.", ["Bupropiona", "Perfil"]],
      ["Qual o perfil da mirtazapina?", "Antagonista alfa-2, 5-HT2, 5-HT3 e H1: sedação e aumento do apetite com ganho de peso, pouca disfunção sexual. Boa opção com insônia e inapetência; seda mais em doses baixas.", ["Mirtazapina", "Perfil"]],
      ["Por que os tricíclicos são perigosos na overdose?", "Bloqueiam canais de sódio cardíacos (QRS alargado, arritmias), além de efeitos anticolinérgicos, anti-histamínicos e alfa-1 (hipotensão ortostática). Na intoxicação com QRS acima de 100 ms: bicarbonato de sódio.", ["Tricíclicos", "Intoxicação"]],
      ["Qual o risco dos IMAO e o intervalo de troca?", "Crise hipertensiva com tiramina (queijos curados, embutidos, vinho tinto, chope) e simpatomiméticos. Intervalo de 2 semanas entre IMAO e ISRS, e de 5 semanas após fluoxetina.", ["IMAO", "Interações"]],
      ["Qual efeito adverso raro e importante da trazodona?", "Priapismo. É sedativa (antagonista 5-HT2A e H1) e muito usada para insônia.", ["Trazodona", "Efeitos adversos"]],
      ["Qual o alerta de suicidalidade dos antidepressivos?", "Aumento de ideação e comportamento suicida em menores de 25 anos no início do tratamento: monitorar de perto nas primeiras semanas.", ["Antidepressivos", "Suicídio"]],
      ["Quanto tempo esperar a resposta e manter o antidepressivo?", "Avaliar resposta após 4 a 6 semanas em dose adequada. Após remissão do 1º episódio, manter por 6 a 12 meses; com 3 ou mais episódios, manutenção prolongada.", ["Antidepressivos", "Duração"]],
      ["Qual o risco do antidepressivo no transtorno bipolar?", "Virada maníaca ou ciclagem, maior com tricíclicos e IRSN e em monoterapia. No bipolar I, não usar antidepressivo sem estabilizador.", ["Antidepressivos", "Bipolar"]],
      ["Qual o cuidado com a agomelatina?", "Agonista melatoninérgico (MT1/MT2) e antagonista 5-HT2C: monitorar enzimas hepáticas.", ["Agomelatina", "Monitorização"]],
    ]),

    deck("pg-esquizofrenia-psicoses", "Esquizofrenia e psicoses", "Psiquiatria Geral", 5, [
      ["Quais os critérios da esquizofrenia no DSM-5-TR?", "2 ou mais de: delírios, alucinações, discurso desorganizado, comportamento desorganizado ou catatônico, sintomas negativos (ao menos um dos 3 primeiros), por 1 mês ativo; sinais contínuos por 6 meses ou mais, com prejuízo funcional.", ["Esquizofrenia", "Diagnóstico"]],
      ["Como a duração separa os transtornos psicóticos?", "Psicótico breve: 1 dia a menos de 1 mês, com retorno completo. Esquizofreniforme: 1 a menos de 6 meses. Esquizofrenia: 6 meses ou mais.", ["Psicoses", "Duração"]],
      ["O que caracteriza o transtorno delirante?", "Um ou mais delírios por 1 mês ou mais, sem critério A de esquizofrenia; funcionamento pouco prejudicado fora do tema delirante. Subtipos: erotomaníaco, grandioso, ciumento, persecutório, somático, misto.", ["Psicoses", "Transtorno delirante"]],
      ["O que define o transtorno esquizoafetivo?", "Episódio de humor maior junto com sintomas de esquizofrenia, mais delírios ou alucinações por 2 semanas ou mais sem episódio de humor; os sintomas de humor ocupam a maior parte da duração total da doença.", ["Psicoses", "Esquizoafetivo"]],
      ["Quais os sintomas de primeira ordem de Schneider?", "Sonorização do pensamento, vozes que dialogam, vozes que comentam, vivências de influência corporal, roubo, imposição e difusão do pensamento, percepção delirante e vivências de influência na vontade e nos sentimentos.", ["Esquizofrenia", "Psicopatologia"], "Não são patognomônicos: aparecem também em mania e quadros orgânicos."],
      ["Quais são os sintomas negativos?", "Afeto embotado, alogia, avolição, anedonia e associabilidade. Associam-se a pior prognóstico e respondem mal aos antipsicóticos.", ["Esquizofrenia", "Sintomas negativos"]],
      ["Quais fatores indicam bom prognóstico na esquizofrenia?", "Início tardio e agudo, fator precipitante, bom funcionamento pré-mórbido, sintomas de humor, predomínio de sintomas positivos, ser casado, sexo feminino e história familiar de transtorno do humor.", ["Esquizofrenia", "Prognóstico"]],
      ["Quais dados epidemiológicos da esquizofrenia caem em prova?", "Prevalência em torno de 0,3 a 0,7%. Início mais precoce em homens (18-25 anos) que em mulheres (25-35, com segundo pico após 40). Risco de cerca de 10% com parente de 1º grau e 40 a 50% em gêmeo monozigótico.", ["Esquizofrenia", "Epidemiologia"]],
      ["Como é a esquizofrenia de início precoce?", "Antes dos 18 anos (muito precoce: antes dos 13, rara): início mais insidioso, mais sintomas negativos e pior prognóstico. Diferenciar de TEA e de transtornos do humor.", ["Esquizofrenia", "Infância e adolescência"]],
      ["O que investigar e como tratar o primeiro episódio psicótico?", "Afastar causas orgânicas e substâncias (hemograma, glicemia, função tireoidiana, sífilis e HIV, neuroimagem conforme a clínica). Antipsicótico na menor dose eficaz, mantido por pelo menos 1 a 2 anos.", ["Psicoses", "Primeiro episódio"]],
      ["Quais as hipóteses neuroquímicas da esquizofrenia?", "Dopaminérgica: hiperatividade mesolímbica (sintomas positivos) e hipoatividade mesocortical (negativos e cognitivos). Glutamatérgica: hipofunção do receptor NMDA (cetamina e fenciclidina reproduzem sintomas positivos e negativos).", ["Esquizofrenia", "Neurobiologia"]],
      ["Como diagnosticar e tratar a catatonia?", "3 ou mais de 12 sinais (estupor, catalepsia, flexibilidade cérea, mutismo, negativismo, postura, maneirismo, estereotipia, agitação, caretas, ecolalia, ecopraxia). Tratamento: lorazepam (inclusive como teste) e ECT.", ["Catatonia", "Tratamento"], "Evite antipsicótico potente na catatonia: risco de síndrome neuroléptica maligna."],
      ["Por que a psicose pós-parto é emergência?", "Começa geralmente nas primeiras semanas após o parto, tem forte ligação com transtorno bipolar e traz risco de suicídio e infanticídio. Exige internação.", ["Psicoses", "Pós-parto"]],
      ["Qual a mortalidade associada à esquizofrenia?", "Expectativa de vida reduzida em 15 a 20 anos, principalmente por doença cardiovascular e metabólica. Cerca de 5% morrem por suicídio, com risco maior nos primeiros anos.", ["Esquizofrenia", "Mortalidade"]],
    ]),

    deck("pia-tea-neurodesenvolvimento", "TEA e neurodesenvolvimento", "PIA", 5, [
      ["Quais os critérios do transtorno do espectro autista no DSM-5-TR?", "A: déficits persistentes na comunicação e interação social (os 3: reciprocidade socioemocional, comunicação não verbal, relacionamentos). B: 2 ou mais de 4 padrões restritos e repetitivos (estereotipias, insistência na mesmice, interesses restritos intensos, alteração sensorial). Início no período do desenvolvimento.", ["TEA", "Diagnóstico"]],
      ["Como se classifica a gravidade no TEA?", "Níveis 1, 2 e 3 (exige apoio, apoio substancial, apoio muito substancial), para cada domínio. Especificadores: com ou sem deficiência intelectual, com ou sem comprometimento da linguagem, associado a condição genética ou médica, com catatonia.", ["TEA", "Gravidade"]],
      ["Quando aplicar o M-CHAT-R/F?", "Rastreio de autismo entre 16 e 30 meses; recomendado de rotina nas consultas de 18 e 24 meses.", ["TEA", "Rastreio"]],
      ["Quais os sinais de alerta para TEA?", "Sem balbucio ou gestos (como apontar) aos 12 meses, sem palavras aos 16 meses, sem frases espontâneas de 2 palavras aos 24 meses, falta de atenção compartilhada e qualquer perda de linguagem ou habilidade social.", ["TEA", "Sinais de alerta"]],
      ["Quais dados epidemiológicos do TEA?", "Prevalência em torno de 1 a 2% (cerca de 1 em 36 crianças nos EUA), cerca de 4 meninos para cada menina; nas meninas a apresentação costuma ser mais sutil.", ["TEA", "Epidemiologia"]],
      ["Quais as comorbidades e a investigação genética do TEA?", "Deficiência intelectual (cerca de 30%), epilepsia, TDAH, ansiedade, distúrbios do sono e gastrointestinais. Investigação: microarray cromossômico (1ª linha) e pesquisa de X frágil.", ["TEA", "Comorbidades"]],
      ["Como se trata o TEA?", "Intervenção comportamental precoce e intensiva (ABA, modelo Denver), fonoaudiologia e terapia ocupacional. Não há remédio para os sintomas centrais; risperidona e aripiprazol são aprovados para irritabilidade e agressividade.", ["TEA", "Tratamento"]],
      ["Como é a síndrome de Rett?", "Meninas, mutação MECP2: desenvolvimento normal até 6 a 18 meses, depois regressão, perda do uso intencional das mãos com estereotipias de 'lavar as mãos', desaceleração do perímetro cefálico e alterações respiratórias.", ["Neurodesenvolvimento", "Rett"]],
      ["Quais as características da síndrome do X frágil?", "Mutação no FMR1 (expansão CGG acima de 200), principal causa herdada de deficiência intelectual: face alongada, orelhas grandes, macroorquidia após a puberdade, hiperextensibilidade articular e traços autistas.", ["Neurodesenvolvimento", "X frágil"]],
      ["Como o DSM-5 define a gravidade da deficiência intelectual?", "Pelo funcionamento adaptativo (domínios conceitual, social e prático), não pelo QI. Requer déficits intelectuais e adaptativos com início no desenvolvimento. Causa genética mais comum: síndrome de Down.", ["Deficiência intelectual", "Diagnóstico"]],
      ["Como diferenciar transtorno da comunicação social (pragmática) de TEA?", "Na comunicação social há déficit no uso social da linguagem sem padrões restritos e repetitivos. Havendo padrões repetitivos, o diagnóstico é TEA.", ["Neurodesenvolvimento", "Comunicação"]],
      ["Quais os critérios e o tratamento da síndrome de Tourette?", "Múltiplos tiques motores e pelo menos 1 vocal, por mais de 1 ano desde o primeiro tique, com início antes dos 18 anos. Comorbidade com TDAH e TOC. Tratamento: intervenção comportamental (reversão de hábito), clonidina ou guanfacina e antipsicóticos (aripiprazol, haloperidol).", ["Tiques", "Tourette"]],
      ["O que define o transtorno específico da aprendizagem?", "Dificuldade persistente em leitura (dislexia), escrita ou matemática (discalculia) por 6 meses ou mais apesar de intervenção, abaixo do esperado para a idade e não explicada por deficiência intelectual.", ["Neurodesenvolvimento", "Aprendizagem"]],
    ]),

    deck("psicofarmaco-antipsicoticos", "Antipsicóticos", "Psicofarmacologia", 5, [
      ["Como diferem os antipsicóticos típicos de alta e baixa potência?", "Alta potência (haloperidol): mais efeitos extrapiramidais e hiperprolactinemia. Baixa potência (clorpromazina): mais sedação, efeitos anticolinérgicos e hipotensão ortostática.", ["Típicos", "Efeitos adversos"]],
      ["Em que ordem aparecem os efeitos extrapiramidais e como tratar?", "Distonia aguda (horas a dias; biperideno), acatisia (dias a semanas; propranolol, reduzir dose), parkinsonismo (semanas; reduzir dose ou anticolinérgico) e discinesia tardia (meses a anos; trocar para clozapina, inibidores de VMAT2).", ["Extrapiramidais", "Tratamento"], "Anticolinérgicos pioram a discinesia tardia."],
      ["Quais os sinais da síndrome neuroléptica maligna?", "Febre, rigidez muscular em cano de chumbo, alteração da consciência e instabilidade autonômica, com CPK elevada e leucocitose, em dias. Suspender o antipsicótico, suporte intensivo, dantrolene ou bromocriptina.", ["SNM", "Emergência"]],
      ["Quando indicar clozapina?", "Esquizofrenia refratária (falha de 2 ou mais antipsicóticos em dose e tempo adequados) e risco de suicídio persistente: é o único antipsicótico que comprovadamente reduz suicídio na esquizofrenia.", ["Clozapina", "Indicações"]],
      ["Quais os riscos da clozapina e a monitorização?", "Agranulocitose (hemograma semanal nas primeiras 18 semanas e depois mensal), convulsões dependentes da dose, miocardite nas primeiras semanas, sialorreia, constipação grave (íleo), ganho de peso e síndrome metabólica, sedação e hipotensão.", ["Clozapina", "Efeitos adversos"]],
      ["Quais antipsicóticos dão mais e menos alteração metabólica?", "Mais: clozapina e olanzapina. Intermediários: quetiapina e risperidona. Menos: aripiprazol, ziprasidona e lurasidona. Monitorar peso, cintura, PA, glicemia e lipídios.", ["Atípicos", "Metabólico"]],
      ["Quais antipsicóticos mais elevam a prolactina?", "Risperidona, paliperidona e típicos de alta potência: amenorreia, galactorreia, disfunção sexual e osteoporose. O aripiprazol (agonista parcial D2) reduz a prolactina.", ["Atípicos", "Prolactina"]],
      ["Quais antipsicóticos mais prolongam o QT?", "Ziprasidona, tioridazina e haloperidol intravenoso em doses altas. Atenção ao ECG e aos eletrólitos.", ["Antipsicóticos", "QT"]],
      ["Qual o perfil do aripiprazol?", "Agonista parcial D2 e 5-HT1A: pouco ganho de peso e sem hiperprolactinemia; a acatisia é o efeito adverso mais comum.", ["Aripiprazol", "Perfil"]],
      ["Quando usar antipsicótico de depósito?", "Má adesão ou preferência do paciente. Ex.: decanoato de haloperidol, palmitato de paliperidona, aripiprazol e risperidona de longa ação. Testar a tolerância oral antes.", ["Depósito", "Adesão"]],
      ["Qual o alerta dos antipsicóticos em idosos com demência?", "Aumento de mortalidade e de AVC. Usar só quando necessário, na menor dose e pelo menor tempo.", ["Antipsicóticos", "Idosos"]],
      ["Qual antipsicótico usar na psicose da doença de Parkinson?", "Quetiapina ou clozapina, pela baixa ocupação de D2 e pouco efeito extrapiramidal. Evitar típicos e risperidona.", ["Antipsicóticos", "Parkinson"]],
      ["Quando considerar que houve falha de um antipsicótico?", "Após cerca de 4 a 6 semanas em dose adequada e com adesão confirmada. Duas falhas adequadas definem refratariedade e indicam clozapina.", ["Antipsicóticos", "Refratariedade"]],
    ]),

    deck("pia-tdah-disruptivos", "TDAH e comportamento disruptivo", "PIA", 5, [
      ["Quais os critérios do TDAH no DSM-5-TR?", "6 ou mais sintomas de desatenção e/ou de hiperatividade-impulsividade (5 a partir dos 17 anos), por 6 meses ou mais, vários antes dos 12 anos, presentes em 2 ou mais ambientes e com prejuízo funcional.", ["TDAH", "Diagnóstico"]],
      ["Quais as apresentações do TDAH e como evoluem?", "Predominantemente desatenta, predominantemente hiperativa-impulsiva e combinada. A apresentação pode mudar: a hiperatividade diminui com a idade e a desatenção tende a persistir.", ["TDAH", "Curso"]],
      ["Qual a prevalência do TDAH?", "Cerca de 5% das crianças e 2,5% dos adultos; mais comum em meninos (cerca de 2:1), e as meninas têm mais apresentação desatenta.", ["TDAH", "Epidemiologia"]],
      ["Qual o tratamento do TDAH conforme a idade?", "Pré-escolares (4-5 anos): treinamento parental comportamental primeiro. Escolares e adolescentes: estimulantes (metilfenidato, lisdexanfetamina) como 1ª linha, com intervenções psicossociais. Não estimulantes: atomoxetina, clonidina, guanfacina.", ["TDAH", "Tratamento"]],
      ["Quais os efeitos adversos dos estimulantes?", "Redução do apetite, insônia, cefaleia, dor abdominal, aumento discreto de FC e PA e leve desaceleração do crescimento. Investigar história cardíaca pessoal e familiar antes.", ["TDAH", "Estimulantes"], "Tiques não são contraindicação absoluta: muitas vezes os estimulantes podem ser mantidos."],
      ["Quando preferir atomoxetina?", "Quando há abuso de substâncias, ansiedade ou tiques importantes. Efeito pleno em semanas; tem alerta de ideação suicida.", ["TDAH", "Atomoxetina"]],
      ["O que caracteriza o transtorno de oposição desafiante (TOD)?", "Humor raivoso ou irritável, comportamento questionador e desafiante e índole vingativa, por 6 meses ou mais, com 4 ou mais sintomas, na interação com pelo menos uma pessoa que não seja irmão. Sem violação grave de direitos alheios.", ["Disruptivos", "TOD"]],
      ["O que caracteriza o transtorno da conduta?", "Violação de direitos básicos dos outros ou de normas sociais: agressão a pessoas ou animais, destruição de propriedade, falsidade ou furto e violações graves de regras (3 ou mais de 15 em 12 meses). Tipos: início na infância (antes dos 10, pior prognóstico) ou na adolescência.", ["Disruptivos", "Conduta"]],
      ["Qual a relação entre transtorno da conduta e personalidade antissocial?", "O diagnóstico de personalidade antissocial exige 18 anos ou mais e evidência de transtorno da conduta antes dos 15 anos. O especificador 'emoções pró-sociais limitadas' indica pior evolução.", ["Disruptivos", "Antissocial"]],
      ["O que é o transtorno disruptivo da desregulação do humor?", "Explosões de raiva graves (3 ou mais por semana) e humor irritável persistente entre elas, por 12 meses, em 2 ou mais ambientes; diagnóstico entre 6 e 18 anos, com início antes dos 10. Evolui mais para depressão e ansiedade do que para bipolar.", ["Disruptivos", "Desregulação do humor"]],
      ["Quais as comorbidades frequentes do TDAH?", "TOD (cerca de metade), transtornos de aprendizagem, ansiedade, tiques e uso de substâncias. O tratamento com estimulante não aumenta o risco de uso de substâncias.", ["TDAH", "Comorbidades"]],
    ]),

    deck("pg-bipolar-mania", "Transtorno bipolar e mania", "Psiquiatria Geral", 5, [
      ["Quais os critérios de um episódio maníaco?", "Humor elevado, expansivo ou irritável com energia aumentada por 1 semana ou mais (ou qualquer duração se houver internação), com 3 ou mais sintomas (4 se o humor for só irritável), com prejuízo acentuado, psicose ou necessidade de internação.", ["Bipolar", "Mania"]],
      ["Quais os sintomas da mania (DIGFAST)?", "Distratibilidade, Impulsividade (indiscrição), Grandiosidade, Fuga de ideias, Atividade aumentada, Sono diminuído e Taquilalia (pressão para falar).", ["Bipolar", "Mania"]],
      ["Como a hipomania difere da mania?", "Dura pelo menos 4 dias, é percebida por outros e não causa prejuízo acentuado, psicose ou internação.", ["Bipolar", "Hipomania"]],
      ["Diferencie bipolar I, bipolar II e ciclotimia.", "Bipolar I: ao menos 1 episódio maníaco (depressão não é obrigatória). Bipolar II: ao menos 1 hipomania e 1 depressão maior, nunca mania. Ciclotimia: 2 anos ou mais (1 ano em jovens) de sintomas hipomaníacos e depressivos subsindrômicos.", ["Bipolar", "Classificação"]],
      ["Mania durante o uso de antidepressivo conta para bipolar I?", "Sim, se a mania persistir em nível sindrômico além do efeito fisiológico do tratamento.", ["Bipolar", "Antidepressivo"]],
      ["O que é ciclagem rápida?", "4 ou mais episódios de humor em 12 meses. Associa-se a hipotireoidismo, uso de antidepressivo e sexo feminino; responde pior ao lítio.", ["Bipolar", "Especificadores"]],
      ["Como tratar a mania aguda?", "Lítio, valproato ou antipsicótico atípico; na mania grave ou psicótica, combinar estabilizador e antipsicótico. Suspender antidepressivos. ECT nos refratários e na gestação.", ["Bipolar", "Mania aguda"]],
      ["Quais opções para depressão bipolar?", "Quetiapina, lurasidona, lítio, lamotrigina (mais na prevenção), olanzapina com fluoxetina e cariprazina. Evitar antidepressivo em monoterapia.", ["Bipolar", "Depressão bipolar"]],
      ["Qual a manutenção do transtorno bipolar?", "Lítio é o padrão-ouro e reduz suicídio. Lamotrigina previne mais o polo depressivo; valproato e atípicos (quetiapina, aripiprazol) são alternativas.", ["Bipolar", "Manutenção"]],
      ["Quais pistas sugerem bipolaridade num quadro depressivo?", "Início antes dos 25 anos, história familiar de bipolar, depressão pós-parto, sintomas atípicos (hipersonia, hiperfagia), sintomas psicóticos, episódios curtos e recorrentes e virada com antidepressivo.", ["Bipolar", "Diagnóstico"]],
      ["Quais dados epidemiológicos do transtorno bipolar?", "Bipolar I em cerca de 1% da população, sem diferença entre os sexos; bipolar II mais comum em mulheres. Início típico entre 18 e 25 anos, com alto risco de suicídio.", ["Bipolar", "Epidemiologia"]],
      ["Quais estabilizadores evitar na gestação?", "Valproato é contraindicado (defeitos do tubo neural e prejuízo cognitivo). Lítio associa-se à anomalia de Ebstein, com risco absoluto baixo. Lamotrigina é relativamente segura. O risco de recaída pós-parto é alto.", ["Bipolar", "Gestação"]],
    ]),

    deck("pg-psicopatologia", "Psicopatologia e exame mental", "Psiquiatria Geral", 4, [
      ["Diferencie alucinação, ilusão e pseudoalucinação.", "Alucinação: percepção sem objeto. Ilusão: percepção deformada de um objeto real. Pseudoalucinação: vivida no espaço subjetivo (interno), sem caráter de realidade objetiva.", ["Sensopercepção", "Alucinação"]],
      ["O que cada modalidade de alucinação sugere?", "Auditivas: esquizofrenia. Visuais: causa orgânica (delirium, substâncias, demência com corpos de Lewy). Olfativas e gustativas: epilepsia do lobo temporal. Táteis: abstinência alcoólica, cocaína (formigamento) e delírio de infestação.", ["Sensopercepção", "Alucinação"]],
      ["Alucinações hipnagógicas e hipnopômpicas são patológicas?", "Não necessariamente: ocorrem ao adormecer (hipnagógicas) e ao despertar (hipnopômpicas) em pessoas saudáveis, e são frequentes na narcolepsia.", ["Sensopercepção", "Sono"]],
      ["Diferencie delírio primário e ideia deliroide (Jaspers).", "Delírio primário é incompreensível e não deriva de outras vivências. Ideia deliroide (secundária) é compreensível a partir de um afeto ou vivência, como na depressão ou na mania.", ["Pensamento", "Delírio"]],
      ["Quais as características do delírio segundo Jaspers?", "Convicção extraordinária, impossibilidade de modificação pela experiência ou argumentação e impossibilidade ou absurdo do conteúdo.", ["Pensamento", "Delírio"]],
      ["Quais alterações do curso e da forma do pensamento caem em prova?", "Curso: aceleração e fuga de ideias (mania), lentificação (depressão), bloqueio (esquizofrenia). Forma: tangencialidade, circunstancialidade (chega ao ponto por rodeios), afrouxamento de associações, descarrilamento, salada de palavras e neologismos.", ["Pensamento", "Forma e curso"]],
      ["Diferencie alterações quantitativas e qualitativas da consciência.", "Quantitativas: obnubilação, sonolência, torpor e coma. Qualitativas: estreitamento (estado crepuscular) e estados dissociativos.", ["Consciência", "Alterações"]],
      ["O que é a lei de Ribot?", "Nas lesões progressivas de memória, as lembranças mais recentes se perdem antes das mais antigas. Confabulação é típica da síndrome de Korsakoff.", ["Memória", "Amnésia"]],
      ["Diferencie humor e afeto.", "Humor é o estado emocional basal e sustentado, relatado pelo paciente; afeto é a expressão emocional observada no momento. Alterações do afeto: embotamento, labilidade e incongruência (paratimia).", ["Afetividade", "Humor"]],
      ["Diferencie despersonalização e desrealização.", "Despersonalização: estranheza em relação a si mesmo. Desrealização: estranheza em relação ao mundo. Em ambas a crítica (teste de realidade) está preservada.", ["Consciência do eu", "Dissociação"]],
      ["Quais as síndromes delirantes com nome próprio?", "Capgras (pessoa substituída por um sósia), Fregoli (perseguidor disfarçado em várias pessoas), Cotard (delírio niilista, depressão psicótica grave), Ekbom (infestação parasitária) e De Clérambault (erotomania).", ["Pensamento", "Síndromes delirantes"]],
      ["O que indicam perseveração, ecolalia e verbigeração?", "Perseveração (repetir uma resposta já dada): lesão frontal. Ecolalia (repetir a fala do outro): catatonia, TEA, demência. Verbigeração (repetir palavras sem sentido): esquizofrenia crônica.", ["Linguagem", "Sinais"]],
    ]),

    deck("pg-personalidade", "Transtornos da personalidade", "Psiquiatria Geral", 4, [
      ["Quais os transtornos de cada cluster?", "A (estranhos): paranoide, esquizoide, esquizotípica. B (dramáticos): antissocial, borderline, histriônica, narcisista. C (ansiosos): evitativa, dependente, obsessivo-compulsiva.", ["Personalidade", "Clusters"]],
      ["Quais os critérios centrais do borderline e o tratamento?", "Instabilidade das relações, da autoimagem e dos afetos, com impulsividade marcante (5 de 9): medo de abandono, autolesão e ameaças suicidas, vazio crônico, raiva intensa, paranoia ou dissociação transitórias. Tratamento principal: psicoterapia (DBT, mentalização, terapia focada na transferência).", ["Personalidade", "Borderline"], "Medicamentos tratam só sintomas-alvo; não existe remédio para o transtorno."],
      ["Quais os requisitos da personalidade antissocial?", "18 anos ou mais, evidência de transtorno da conduta antes dos 15 anos e padrão de desrespeito e violação dos direitos alheios desde os 15 (3 ou mais de 7 critérios).", ["Personalidade", "Antissocial"]],
      ["Diferencie esquizoide, esquizotípica e evitativa.", "Esquizoide: não deseja relações, indiferente, afeto frio. Esquizotípica: excentricidade, pensamento mágico, ideias de referência, experiências perceptivas incomuns (ligada geneticamente à esquizofrenia). Evitativa: deseja relações, mas as evita por medo de crítica e rejeição.", ["Personalidade", "Cluster A x C"]],
      ["O que caracteriza a personalidade paranoide?", "Desconfiança e suspeita generalizadas, interpretando os motivos dos outros como malévolos, guardando rancores, sem delírio fixo.", ["Personalidade", "Paranoide"]],
      ["Diferencie histriônica e narcisista.", "Histriônica: busca de atenção, emoções superficiais e mutáveis, sedução inadequada, sugestionabilidade. Narcisista: grandiosidade, necessidade de admiração, falta de empatia, senso de merecimento e arrogância.", ["Personalidade", "Cluster B"]],
      ["Como diferenciar personalidade obsessivo-compulsiva de TOC?", "A personalidade é egossintônica: perfeccionismo, rigidez, preocupação com ordem e controle, devoção ao trabalho, avareza. No TOC há obsessões e compulsões egodistônicas.", ["Personalidade", "Obsessivo-compulsiva"]],
      ["O que caracteriza a personalidade dependente?", "Necessidade excessiva de ser cuidado, submissão, dificuldade de tomar decisões sem conselho e desconforto ao ficar sozinho.", ["Personalidade", "Dependente"]],
      ["Pode-se diagnosticar transtorno da personalidade antes dos 18 anos?", "Sim, se os traços estiverem presentes por pelo menos 1 ano, exceto a personalidade antissocial, que exige 18 anos.", ["Personalidade", "Diagnóstico"]],
      ["Quais defesas são típicas de cada personalidade?", "Borderline: cisão e identificação projetiva. Paranoide: projeção. Obsessiva: isolamento do afeto, intelectualização, formação reativa. Histriônica: repressão e dissociação.", ["Personalidade", "Defesas"]],
      ["Como o modelo alternativo do DSM-5 e a CID-11 descrevem a personalidade?", "Modelo alternativo: prejuízo no funcionamento (identidade, autodireção, empatia, intimidade) e 5 domínios de traços (afetividade negativa, distanciamento, antagonismo, desinibição, psicoticismo). CID-11: um único transtorno, graduado por gravidade, com traços e padrão borderline.", ["Personalidade", "Modelos"]],
    ]),

    deck("pg-saude-mental-coletiva", "Saúde mental coletiva", "Psiquiatria Geral", 4, [
      ["Quais os componentes da RAPS (Portaria 3.088/2011)?", "Atenção básica (UBS, consultório na rua, centros de convivência), atenção psicossocial especializada (CAPS), urgência e emergência, atenção residencial de caráter transitório (unidades de acolhimento), atenção hospitalar (leitos em hospital geral), desinstitucionalização (residências terapêuticas) e reabilitação psicossocial.", ["RAPS", "Componentes"]],
      ["Qual a população mínima para cada tipo de CAPS?", "CAPS I: 15 mil habitantes. CAPS II, CAPS i e CAPS AD: 70 mil. CAPS III e CAPS AD III (24 horas, com acolhimento noturno): 150 mil.", ["CAPS", "Tipos"]],
      ["O que são as residências terapêuticas e o De Volta para Casa?", "Residências terapêuticas são moradias para egressos de longas internações psiquiátricas. O Programa De Volta para Casa (Lei 10.708/2003) paga auxílio-reabilitação a egressos de internação de 2 anos ou mais.", ["Desinstitucionalização", "SRT"]],
      ["O que é matriciamento (apoio matricial)?", "Suporte técnico-pedagógico e assistencial de uma equipe especializada às equipes da atenção básica, com corresponsabilização: discussão de casos, interconsulta, atendimento conjunto e construção de PTS.", ["Atenção básica", "Matriciamento"]],
      ["O que é o Projeto Terapêutico Singular (PTS)?", "Conjunto de condutas construído pela equipe com o usuário, em 4 etapas: diagnóstico situacional, definição de metas, divisão de responsabilidades (técnico de referência) e reavaliação.", ["CAPS", "PTS"]],
      ["O que é redução de danos?", "Estratégia de saúde pública que busca diminuir as consequências negativas do uso de drogas sem exigir a abstinência como condição para o cuidado.", ["Álcool e drogas", "Redução de danos"]],
      ["Quais os marcos da reforma psiquiátrica brasileira?", "Declaração de Caracas (1990), influência da psiquiatria democrática italiana (Basaglia) e Lei 10.216/2001 (Paulo Delgado), que garante direitos e redireciona o cuidado para serviços comunitários.", ["Reforma psiquiátrica", "História"]],
      ["Quais os níveis de prevenção em saúde mental?", "Primária (evitar que o transtorno ocorra), secundária (diagnóstico e tratamento precoces), terciária (reduzir incapacidade e reabilitar) e quaternária (evitar iatrogenia e medicalização excessiva).", ["Prevenção", "Níveis"]],
      ["Onde deve ocorrer a maior parte do cuidado em saúde mental?", "Na atenção básica: os transtornos mentais comuns (ansiedade e depressão) são os mais frequentes ali. A internação deve ser breve, preferencialmente em leitos de hospital geral.", ["Atenção básica", "Organização"]],
      ["O que são a unidade de acolhimento e o consultório na rua?", "Unidade de acolhimento: moradia transitória (até 6 meses) para usuários de álcool e drogas acompanhados pelo CAPS, adulto ou infantojuvenil. Consultório na rua: equipe que atende a população em situação de rua.", ["RAPS", "Serviços"]],
    ]),

    deck("pg-sono", "Sono", "Psiquiatria Geral", 3, [
      ["Quais os critérios de insônia crônica e o tratamento de 1ª linha?", "Dificuldade de iniciar ou manter o sono ou despertar precoce, 3 noites por semana ou mais, por 3 meses ou mais, com prejuízo diurno. 1ª linha: TCC para insônia (controle de estímulos, restrição de sono, reestruturação cognitiva, relaxamento).", ["Insônia", "Tratamento"], "Higiene do sono isolada tem eficácia limitada."],
      ["Quais medicamentos para insônia e seus cuidados?", "Hipnóticos Z (zolpidem: comportamentos complexos do sono), benzodiazepínicos (tolerância, quedas), doxepina em dose baixa, trazodona (off-label), antagonistas da orexina (suvorexante, lemborexante, daridorexante) e melatonina.", ["Insônia", "Fármacos"]],
      ["Como se diagnostica e gradua a apneia obstrutiva do sono?", "Polissonografia: IAH de 5 ou mais com sintomas, ou 15 ou mais isolado. Leve 5-15, moderada 15-30, grave 30 ou mais. Tratamento: CPAP e perda de peso; benzodiazepínicos pioram.", ["Apneia", "Diagnóstico"]],
      ["O que define a narcolepsia e como tratar?", "Sonolência diurna excessiva por 3 meses com cataplexia e/ou hipocretina baixa no líquor e/ou latência média de sono de 8 minutos ou menos no TLMS com 2 ou mais SOREMPs. Tratamento: modafinil, metilfenidato, pitolisanto; oxibato de sódio e antidepressivos para cataplexia.", ["Narcolepsia", "Diagnóstico"]],
      ["Diferencie parassonias NREM e REM.", "NREM (sono N3, primeiro terço da noite): sonambulismo, terror noturno, despertar confusional, sem lembrança. REM (último terço): pesadelos com lembrança vívida e transtorno comportamental do sono REM.", ["Parassonias", "Classificação"]],
      ["Por que o transtorno comportamental do sono REM importa?", "Encenação dos sonhos por perda da atonia do REM, em homens idosos; é marcador prodrômico de sinucleinopatias (Parkinson, Lewy, atrofia de múltiplos sistemas). Tratamento: segurança do ambiente, melatonina ou clonazepam.", ["Parassonias", "REM"]],
      ["Como abordar a síndrome das pernas inquietas?", "Urgência de mover as pernas, pior em repouso e à noite, aliviada pelo movimento. Dosar ferritina e repor ferro se abaixo de 75. Tratamento: gabapentinoides (1ª linha) ou agonistas dopaminérgicos (risco de piora paradoxal, 'augmentation').", ["Pernas inquietas", "Tratamento"], "ISRS, mirtazapina e antipsicóticos podem piorar o quadro."],
      ["Como é a arquitetura normal do sono?", "Ciclos de cerca de 90 minutos: N1, N2 (fusos e complexos K), N3 (ondas lentas, no primeiro terço da noite) e REM (atonia, movimentos oculares rápidos e sonhos, no último terço).", ["Sono normal", "Arquitetura"]],
      ["Quais alterações do sono aparecem na depressão?", "Latência do REM reduzida, aumento da densidade de REM, menos sono N3 e despertar precoce.", ["Sono", "Depressão"]],
      ["Como tratar atraso e avanço de fase do sono?", "Atraso de fase (adolescentes, dormem e acordam tarde): melatonina no início da noite e luz pela manhã. Avanço de fase (idosos): luz no fim da tarde.", ["Ritmo circadiano", "Tratamento"]],
      ["O que é a síndrome de Kleine-Levin?", "Episódios recorrentes de hipersonia com hiperfagia, hipersexualidade e alterações cognitivas, típica de adolescentes do sexo masculino.", ["Hipersonia", "Kleine-Levin"]],
    ]),

    deck("psicofarmaco-estabilizadores", "Estabilizadores do humor", "Psicofarmacologia", 4, [
      ["Qual a faixa terapêutica do lítio e quando coletar?", "0,6 a 1,2 mEq/L (manutenção 0,6 a 1,0). Coletar 12 horas após a última dose; o equilíbrio leva cerca de 5 dias.", ["Lítio", "Nível sérico"]],
      ["Quais os sinais de intoxicação por lítio e a conduta?", "Tremor grosseiro, ataxia, disartria, confusão, vômitos e diarreia, convulsões. Suspender, hidratar e considerar hemodiálise nos casos graves (nível muito alto, sintomas neurológicos graves ou insuficiência renal).", ["Lítio", "Intoxicação"]],
      ["Quais medicamentos aumentam o nível do lítio?", "Tiazídicos, IECA, bloqueadores do receptor de angiotensina e AINEs, além de desidratação e dieta pobre em sódio.", ["Lítio", "Interações"]],
      ["Quais os efeitos adversos do lítio de longo prazo?", "Tremor fino, poliúria e polidipsia (diabetes insípido nefrogênico), hipotireoidismo, hiperparatireoidismo com hipercalcemia, ganho de peso, acne, leucocitose benigna e nefropatia crônica. Monitorar creatinina, TSH e cálcio.", ["Lítio", "Efeitos adversos"]],
      ["Quais os riscos do valproato?", "Ganho de peso, tremor, alopecia, hepatotoxicidade, pancreatite, trombocitopenia, ovários policísticos, hiperamonemia e teratogenicidade (tubo neural). Nível de 50 a 125 µg/mL.", ["Valproato", "Efeitos adversos"]],
      ["Quais os riscos da carbamazepina?", "Indutor enzimático (inclusive de si mesma; reduz anticoncepcional), hiponatremia, agranulocitose e anemia aplástica, Stevens-Johnson (HLA-B*1502 em asiáticos) e teratogenicidade. A oxcarbazepina dá mais hiponatremia e menos indução.", ["Carbamazepina", "Efeitos adversos"]],
      ["Quais os cuidados com a lamotrigina?", "Previne sobretudo depressão bipolar e não trata mania aguda. Risco de rash grave (Stevens-Johnson): titulação lenta. Valproato dobra o nível (usar metade da dose); carbamazepina reduz.", ["Lamotrigina", "Cuidados"]],
      ["Qual a vantagem do lítio sobre os outros estabilizadores?", "Reduz suicídio. Atua inibindo a inositol monofosfatase e a GSK-3 beta.", ["Lítio", "Suicídio"]],
      ["Quais os cuidados com lítio na gestação e no pós-parto?", "Associação com anomalia de Ebstein (risco absoluto baixo). A depuração aumenta na gestação e cai bruscamente após o parto, com risco de intoxicação: monitorar o nível.", ["Lítio", "Gestação"]],
    ]),

    deck("pg-transtornos-alimentares", "Transtornos alimentares", "Psiquiatria Geral", 4, [
      ["Quais os critérios da anorexia nervosa no DSM-5-TR?", "Restrição da ingestão com peso significativamente baixo, medo intenso de ganhar peso (ou comportamento que impede o ganho) e perturbação da imagem corporal. Tipos: restritivo e compulsão alimentar/purgativo.", ["Anorexia", "Diagnóstico"], "Amenorreia deixou de ser critério no DSM-5."],
      ["Como o IMC gradua a anorexia em adultos?", "Leve: 17 ou mais. Moderada: 16 a 16,99. Grave: 15 a 15,99. Extrema: abaixo de 15. Em crianças e adolescentes usa-se o percentil.", ["Anorexia", "Gravidade"]],
      ["Quais os critérios da bulimia nervosa?", "Compulsões alimentares com comportamentos compensatórios (vômitos, laxantes, diuréticos, jejum, exercício) pelo menos 1 vez por semana por 3 meses, autoavaliação dominada por peso e forma, fora de episódio de anorexia. Peso geralmente normal.", ["Bulimia", "Diagnóstico"]],
      ["O que define o transtorno de compulsão alimentar e como tratar?", "Compulsões 1 vez por semana ou mais por 3 meses, com sofrimento e sem comportamentos compensatórios regulares. Tratamento: TCC; lisdexanfetamina e topiramato são opções farmacológicas.", ["Compulsão alimentar", "Tratamento"]],
      ["Quais as complicações dos vômitos autoinduzidos?", "Hipocalemia, alcalose metabólica hipoclorêmica, hipertrofia de parótidas (amilase alta), erosão do esmalte dentário, sinal de Russell (calos no dorso das mãos) e lacerações de Mallory-Weiss.", ["Bulimia", "Complicações"]],
      ["Quais as complicações clínicas da anorexia?", "Bradicardia, hipotensão, hipotermia, lanugo, osteopenia, amenorreia (hipogonadismo hipotalâmico), citopenias, alteração de enzimas hepáticas e QT longo. Tem a maior mortalidade entre os transtornos psiquiátricos.", ["Anorexia", "Complicações"]],
      ["O que é a síndrome de realimentação?", "Nos primeiros dias de realimentação: hipofosfatemia (principal), hipocalemia, hipomagnesemia, deficiência de tiamina, retenção hídrica e insuficiência cardíaca. Monitorar eletrólitos e repor fósforo e tiamina.", ["Anorexia", "Realimentação"]],
      ["Qual o tratamento da anorexia nervosa?", "Restauração do peso e reabilitação nutricional. Em adolescentes, a terapia baseada na família (Maudsley) é 1ª linha. Medicamentos têm pouco efeito (olanzapina pode ajudar no ganho de peso).", ["Anorexia", "Tratamento"], "ISRS não funcionam enquanto o peso está baixo."],
      ["Qual o tratamento da bulimia nervosa?", "TCC (1ª linha) e fluoxetina em dose alta (60 mg/dia).", ["Bulimia", "Tratamento"], "Bupropiona é contraindicada: risco de convulsão."],
      ["O que é o transtorno alimentar restritivo/evitativo (TARE)?", "Restrição por falta de interesse, aversão a características sensoriais dos alimentos ou medo de consequências (engasgo, vômito), sem alteração da imagem corporal. Mais comum em crianças.", ["TARE", "Diagnóstico"]],
      ["O que definem pica e ruminação?", "Pica: ingestão persistente de substâncias não nutritivas por 1 mês ou mais, a partir dos 2 anos (investigar deficiência de ferro ou zinco e gestação). Ruminação: regurgitação repetida do alimento.", ["Alimentares", "Pica"]],
      ["Quando internar na anorexia?", "Instabilidade clínica (bradicardia importante, hipotensão, hipotermia, distúrbio eletrolítico grave, síncope), IMC muito baixo (menor que 15), recusa alimentar aguda, risco de suicídio ou falha do tratamento ambulatorial.", ["Anorexia", "Internação"]],
    ]),

    deck("psicofarmaco-benzodiazepinicos", "Benzodiazepínicos e sedativos", "Psicofarmacologia", 3, [
      ["Qual o mecanismo dos benzodiazepínicos?", "Moduladores alostéricos positivos do receptor GABA-A: aumentam a frequência de abertura do canal de cloro (barbitúricos aumentam a duração). Efeitos: ansiolítico, hipnótico, anticonvulsivante, miorrelaxante e amnésia anterógrada.", ["BZD", "Mecanismo"]],
      ["Classifique BZD pela meia-vida.", "Curta: midazolam, triazolam. Intermediária: alprazolam, lorazepam. Longa: diazepam, clordiazepóxido, clonazepam (os dois primeiros com metabólitos ativos).", ["BZD", "Farmacocinética"]],
      ["Quais BZD preferir em hepatopatas e idosos?", "Lorazepam, oxazepam e temazepam (LOT): só glicuronidação, sem metabolismo oxidativo hepático nem metabólitos ativos.", ["BZD", "Hepatopatia"]],
      ["A intoxicação por BZD é grave?", "Isolada, raramente é fatal; o risco grave está na combinação com álcool, opioides e outros depressores. O flumazenil tem uso restrito: pode precipitar convulsões em usuários crônicos ou com tricíclicos.", ["BZD", "Intoxicação"]],
      ["Como é a abstinência de BZD e como retirar?", "Ansiedade rebote, insônia, tremor, hiperacusia, despersonalização e, nos casos graves, convulsões e delirium (doses altas, meia-vida curta, retirada abrupta). Retirada gradual (10 a 25% a cada 2 a 4 semanas), trocando por BZD de meia-vida longa.", ["BZD", "Abstinência"]],
      ["Por que evitar BZD em idosos?", "Risco de quedas, fraturas, prejuízo cognitivo e delirium; os critérios de Beers recomendam evitar.", ["BZD", "Idosos"]],
      ["Quais os riscos do BZD no fim da gestação?", "Síndrome do bebê hipotônico (floppy infant) e abstinência neonatal.", ["BZD", "Gestação"]],
      ["O que diferencia os hipnóticos Z (zolpidem, zopiclona)?", "Agonistas seletivos da subunidade alfa-1 do GABA-A, com efeito hipnótico. Riscos: amnésia, sonambulismo e comportamentos complexos do sono. Uso por curto prazo.", ["Hipnóticos Z", "Perfil"]],
      ["Qual o perfil da buspirona?", "Agonista parcial 5-HT1A para TAG: não seda, não causa dependência e não interage com álcool; efeito em 2 a 4 semanas.", ["Buspirona", "Perfil"], "Não serve para crise de pânico nem para abstinência de BZD ou álcool."],
      ["Quando o BZD é apropriado?", "Ansiedade aguda, ponte nas primeiras semanas de ISRS, insônia aguda, abstinência alcoólica, catatonia (lorazepam), acatisia e agitação. Evitar uso prolongado.", ["BZD", "Indicações"]],
    ]),

    deck("pg-depressao-suicidio", "Depressão e suicídio no adulto", "Psiquiatria Geral", 5, [
      ["Quais os critérios do episódio depressivo maior?", "5 ou mais de 9 sintomas por 2 semanas ou mais, incluindo humor deprimido ou anedonia: alterações de sono, interesse, culpa, energia, concentração, apetite, psicomotricidade e ideação suicida.", ["Depressão", "Diagnóstico"]],
      ["O luto impede o diagnóstico de depressão maior?", "Não: o DSM-5 retirou a exclusão do luto. O transtorno do luto prolongado (DSM-5-TR) exige 12 meses ou mais após a perda em adultos (6 meses em crianças).", ["Depressão", "Luto"]],
      ["O que define o transtorno depressivo persistente (distimia)?", "Humor deprimido na maior parte do dia, na maioria dos dias, por 2 anos ou mais (1 ano em jovens, podendo ser irritável), com 2 ou mais sintomas e sem intervalo assintomático maior que 2 meses.", ["Depressão", "Distimia"]],
      ["Diferencie depressão melancólica e atípica.", "Melancólica: anedonia, falta de reatividade, piora matinal, despertar precoce, alteração psicomotora, perda de peso e culpa excessiva. Atípica: humor reativo, hipersonia, hiperfagia, sensação de corpo pesado e sensibilidade à rejeição.", ["Depressão", "Especificadores"]],
      ["Como tratar a depressão psicótica?", "Antidepressivo associado a antipsicótico, ou ECT, que tem alta eficácia.", ["Depressão", "Psicótica"]],
      ["Quais as indicações e efeitos da ECT?", "Depressão grave com risco de suicídio, psicótica, catatônica, recusa alimentar, refratariedade e gestação. Efeitos: amnésia transitória e cefaleia. Cautela com hipertensão intracraniana e IAM ou AVC recentes.", ["Depressão", "ECT"]],
      ["O que fazer na depressão resistente?", "Após falha de 2 ou mais antidepressivos adequados: otimizar dose, trocar, combinar (ex.: mirtazapina) ou potencializar (lítio, aripiprazol, quetiapina, T3); escetamina intranasal, ECT e estimulação magnética transcraniana.", ["Depressão", "Resistente"]],
      ["Qual o principal fator de risco para suicídio?", "Tentativa prévia. Outros: transtorno mental (depressão, bipolar, substâncias, esquizofrenia), sexo masculino, isolamento, desemprego, doença crônica, acesso a meios letais e história familiar.", ["Suicídio", "Fatores de risco"], "Mulheres tentam mais; homens morrem mais por suicídio."],
      ["Perguntar sobre suicídio aumenta o risco?", "Não. Avalie ideação, plano, intenção, meios, tentativas prévias e fatores de proteção. Condutas: restringir meios, plano de segurança e seguimento próximo; risco alto indica internação.", ["Suicídio", "Avaliação"]],
      ["Diferencie baby blues e depressão pós-parto.", "Baby blues: transitório, começa nos primeiros dias e melhora em até 2 semanas, sem prejuízo importante. Depressão pós-parto: persiste e prejudica o funcionamento. Rastreio com a escala de Edimburgo (EPDS).", ["Depressão", "Pós-parto"]],
      ["Como diagnosticar e tratar o transtorno disfórico pré-menstrual?", "5 ou mais sintomas na semana anterior à menstruação, que melhoram poucos dias após seu início, confirmados por registro prospectivo em 2 ciclos. Tratamento: ISRS (contínuo ou na fase lútea) e anticoncepcional com drospirenona.", ["Depressão", "TDPM"]],
      ["Quais tratamentos reduzem o risco de suicídio?", "Lítio (transtornos do humor) e clozapina (esquizofrenia). Cetamina e escetamina reduzem a ideação suicida de forma rápida.", ["Suicídio", "Tratamento"]],
    ]),
  ];

  const known = new Set(root.decks.map((item) => item.id));
  for (const item of decks) if (!known.has(item.id)) root.decks.push(item);
})();
